// SPDX-License-Identifier: MPL-2.0
// Bit-exact differential tests of src/d2svg/{geo,label,shape,svgpath}.rs
// against the pinned Go D2 packages. Included as a unit-test module
// from src/d2svg/shape.rs (the items under test are crate-private).
//
// Fixture: tests/fixtures/d2svg-geometry/oracle.json (oracle tier), regenerated by
// recipe d2svg-geometry-oracle (scripts/d2svg-geometry-fixtures.py --oracle; Go oracle
// scripts/d2svg-geometry-oracle.go built inside ../d2 via -overlay with the
// pinned go1.27.0 darwin/arm64 toolchain). Outputs are IEEE-754 bit
// patterns from an ARM64 build, so exact comparison is only claimed on
// aarch64; other targets check structure and report differences.

use super::super::geo::{self, Point, Vector, gomath};
use super::super::label::Position;
use super::super::shape;
use super::super::svgpath;
use serde_json::Value;

fn fixture() -> Value {
    serde_json::from_str(d2_rs_testdata::oracle_fixture!(
        "tests/fixtures/d2svg-geometry/oracle.json"
    ))
    .expect("json")
}

fn f(v: &Value) -> f64 {
    f64::from_bits(u64::from_str_radix(v.as_str().expect("bits string"), 16).expect("hex"))
}

fn p(v: &Value) -> Option<Point> {
    let a = v.as_array()?;
    Some(Point::new(f(&a[0]), f(&a[1])))
}

fn bx(v: &Value) -> Option<geo::Box> {
    let a = v.as_array()?;
    Some(geo::Box::new(
        Point::new(f(&a[0]), f(&a[1])),
        f(&a[2]),
        f(&a[3]),
    ))
}

fn pts(v: &Value) -> Vec<Point> {
    v.as_array()
        .map(|a| a.iter().map(|x| p(x).unwrap()).collect())
        .unwrap_or_default()
}

/// Collects mismatches; exact on aarch64 (the oracle's architecture).
struct Check {
    name: &'static str,
    total: usize,
    errors: Vec<String>,
}

impl Check {
    fn new(name: &'static str) -> Self {
        Check {
            name,
            total: 0,
            errors: Vec::new(),
        }
    }

    fn eq_f(&mut self, what: &str, got: f64, want: f64) {
        self.total += 1;
        if got.to_bits() != want.to_bits() && !(got.is_nan() && want.is_nan()) {
            self.errors.push(format!(
                "{what}: got {got:?} ({:016x}) want {want:?} ({:016x})",
                got.to_bits(),
                want.to_bits()
            ));
        }
    }

    fn eq_p(&mut self, what: &str, got: Option<Point>, want: Option<Point>) {
        match (got, want) {
            (Some(g), Some(w)) => {
                self.eq_f(&format!("{what}.x"), g.x, w.x);
                self.eq_f(&format!("{what}.y"), g.y, w.y);
            }
            (None, None) => self.total += 1,
            _ => {
                self.total += 1;
                self.errors
                    .push(format!("{what}: got {got:?} want {want:?}"));
            }
        }
    }

    fn eq_pts(&mut self, what: &str, got: &[Point], want: &[Point]) {
        if got.len() != want.len() {
            self.total += 1;
            self.errors
                .push(format!("{what}: got {got:?} want {want:?}"));
            return;
        }
        for (i, (g, w)) in got.iter().zip(want).enumerate() {
            self.eq_p(&format!("{what}[{i}]"), Some(*g), Some(*w));
        }
    }

    fn eq_box(&mut self, what: &str, got: Option<geo::Box>, want: Option<geo::Box>) {
        match (got, want) {
            (Some(g), Some(w)) => {
                self.eq_p(&format!("{what}.tl"), Some(g.top_left), Some(w.top_left));
                self.eq_f(&format!("{what}.w"), g.width, w.width);
                self.eq_f(&format!("{what}.h"), g.height, w.height);
            }
            (None, None) => self.total += 1,
            _ => {
                self.total += 1;
                self.errors
                    .push(format!("{what}: got {got:?} want {want:?}"));
            }
        }
    }

    fn eq_s<T: PartialEq + std::fmt::Debug>(&mut self, what: &str, got: T, want: T) {
        self.total += 1;
        if got != want {
            self.errors
                .push(format!("{what}: got {got:?} want {want:?}"));
        }
    }

    fn finish(self) {
        eprintln!(
            "{}: {}/{} values match",
            self.name,
            self.total - self.errors.len(),
            self.total
        );
        if cfg!(target_arch = "aarch64") {
            assert!(
                self.errors.is_empty(),
                "{}: {} of {} differ:\n{}",
                self.name,
                self.errors.len(),
                self.total,
                self.errors
                    .iter()
                    .take(40)
                    .cloned()
                    .collect::<Vec<_>>()
                    .join("\n")
            );
        }
    }
}

#[test]
fn oracle_go_math() {
    let fx = fixture();
    let mut c = Check::new("math");
    for r in fx["math"].as_array().unwrap() {
        let (x, y) = (f(&r["x"]), f(&r["y"]));
        let ax = x.abs();
        c.eq_f(&format!("sin({x:?})"), gomath::sin(x), f(&r["sin"]));
        c.eq_f(&format!("cos({x:?})"), gomath::cos(x), f(&r["cos"]));
        c.eq_f(
            &format!("atan2({y:?},{x:?})"),
            gomath::atan2(y, x),
            f(&r["atan2"]),
        );
        c.eq_f(
            &format!("acos({x:?})"),
            gomath::acos(x % 1.0),
            f(&r["acos"]),
        );
        c.eq_f(&format!("log10({ax:?})"), gomath::log10(ax), f(&r["log10"]));
        c.eq_f(&format!("exp({x:?})"), gomath::exp(x % 700.0), f(&r["exp"]));
        c.eq_f(&format!("pow({x:?},2)"), gomath::pow(x, 2.0), f(&r["pow2"]));
        c.eq_f(&format!("pow({x:?},3)"), gomath::pow(x, 3.0), f(&r["pow3"]));
        c.eq_f(
            &format!("pow({ax:?},1/3)"),
            gomath::pow(ax, 1.0 / 3.0),
            f(&r["pow13"]),
        );
    }
    c.finish();
}

#[test]
fn oracle_geo() {
    let fx = fixture();
    let mut c = Check::new("geo");
    for (i, r) in fx["geo"].as_array().unwrap().iter().enumerate() {
        let (a, cc, d, e) = (
            p(&r["a"]).unwrap(),
            p(&r["c"]).unwrap(),
            p(&r["d"]).unwrap(),
            p(&r["e"]).unwrap(),
        );
        let t = f(&r["t"]);
        let v = a.vector_to(&cc);
        c.eq_f(
            &format!("{i} euclid"),
            geo::euclidean_distance(a.x, a.y, cc.x, cc.y),
            f(&r["euclid"]),
        );
        c.eq_p(
            &format!("{i} interp"),
            Some(a.interpolate(&cc, t)),
            p(&r["interp"]),
        );
        c.eq_f(&format!("{i} len"), v.length(), f(&r["len"]));
        let unit = v.unit();
        c.eq_p(&format!("{i} unit"), Some(unit.to_point()), p(&r["unit"]));
        c.eq_p(
            &format!("{i} add_length"),
            Some(v.add_length(t * 100.0).to_point()),
            p(&r["add_length"]),
        );
        c.eq_f(&format!("{i} radians"), v.radians(), f(&r["radians"]));
        c.eq_f(&format!("{i} degrees"), v.degrees(), f(&r["degrees"]));
        let (nx, ny) = geo::get_unit_normal_vector(a.x, a.y, cc.x, cc.y);
        c.eq_p(
            &format!("{i} normal"),
            Some(Point::new(nx, ny)),
            p(&r["normal"]),
        );
        c.eq_p(
            &format!("{i} isect"),
            geo::intersection_point(&a, &cc, &d, &e),
            p(&r["isect"]),
        );
        c.eq_f(
            &format!("{i} dist_line"),
            e.distance_to_line(&a, &cc),
            f(&r["dist_line"]),
        );
        let radii = r["ell"].as_array().unwrap();
        let ell = geo::Ellipse::new(d, f(&radii[0]), f(&radii[1]));
        c.eq_pts(
            &format!("{i} ell"),
            &ell.intersections(&geo::Segment::new(a, cc)),
            &pts(&r["ell_pts"]),
        );
        let vertical = geo::Segment::new(a, Point::new(a.x, cc.y));
        c.eq_pts(
            &format!("{i} vell"),
            &ell.intersections(&vertical),
            &pts(&r["vell_pts"]),
        );
        let bez = geo::BezierCurve::new(vec![a, cc, d, e]);
        let cut = pts(&r["cut"]);
        c.eq_pts(
            &format!("{i} bez"),
            &bez.intersections(&geo::Segment::new(cut[0], cut[1])),
            &pts(&r["bez_pts"]),
        );
        c.eq_p(
            &format!("{i} bez_at"),
            Some(bez.at(t.abs())),
            p(&r["bez_at"]),
        );
        let route = [a, cc, d, e];
        c.eq_f(
            &format!("{i} route_length"),
            geo::route_length(&route),
            f(&r["route_length"]),
        );
        let (rp, ri) = geo::route_get_point_at_distance(&route, f(&r["route_dist"]));
        c.eq_p(&format!("{i} route_pt"), Some(rp), p(&r["route_pt"]));
        c.eq_s(
            &format!("{i} route_idx"),
            ri as i64,
            r["route_idx"].as_i64().unwrap(),
        );
    }
    // Vector API sanity (Go []float64 arithmetic).
    let v = Vector::new(&[3.0, 4.0]);
    assert_eq!(v.length(), 5.0);
    assert_eq!(v.reverse(), Vector::new(&[-3.0, -4.0]));
    c.finish();
}

#[test]
fn oracle_label() {
    let fx = fixture();
    let mut c = Check::new("label");
    for (i, r) in fx["label"].as_array().unwrap().iter().enumerate() {
        let pos = Position::from_string(r["pos"].as_str().unwrap());
        c.eq_s(
            &format!("{i} string"),
            pos.string(),
            r["pos"].as_str().unwrap(),
        );
        c.eq_s(
            &format!("{i} mirrored"),
            pos.mirrored().string(),
            r["mirrored"].as_str().unwrap(),
        );
        let (w, h, pad) = (f(&r["w"]), f(&r["h"]), f(&r["pad"]));
        let b = bx(&r["box"]).unwrap();
        c.eq_p(
            &format!("{i} {} on_box", pos.string()),
            Some(pos.get_point_on_box(&b, pad, w, h)),
            p(&r["on_box"]),
        );
        let route = pts(&r["route"]);
        let got = pos.try_get_point_on_route(&route, f(&r["stroke"]), f(&r["perc"]), w, h);
        c.eq_p(
            &format!("{i} {} on_route", pos.string()),
            got.map(|g| g.0),
            p(&r["on_route"]),
        );
        c.eq_s(
            &format!("{i} {} route_idx", pos.string()),
            got.map_or(-1, |g| g.1 as i64),
            r["route_idx"].as_i64().unwrap(),
        );
    }
    c.finish();
}

#[test]
fn oracle_svg() {
    let fx = fixture();
    let mut c = Check::new("svg");
    for (i, r) in fx["svg"].as_array().unwrap().iter().enumerate() {
        let (ds, gs) = svgpath::get_stroke_dash_attributes(f(&r["sw"]), f(&r["gap"]));
        c.eq_p(
            &format!("{i} dash"),
            Some(Point::new(ds, gs)),
            p(&r["dash"]),
        );
        let q = pts(&r["p"]);
        let (q1, q2, q3, q4) =
            svgpath::bezier_curve_segment(&q[0], &q[1], &q[2], &q[3], f(&r["t0"]), f(&r["t1"]));
        c.eq_pts(&format!("{i} seg"), &[q1, q2, q3, q4], &pts(&r["seg"]));
        let path = r["path"].as_str().unwrap();
        match svgpath::split_path(path, f(&r["perc"])) {
            Ok((a, b)) => {
                c.eq_s(
                    &format!("{i} split1 {path}"),
                    a.as_str(),
                    r["split"][0].as_str().unwrap(),
                );
                c.eq_s(
                    &format!("{i} split2 {path}"),
                    b.as_str(),
                    r["split"][1].as_str().unwrap(),
                );
            }
            Err(e) => c.eq_s(
                &format!("{i} split err {path}"),
                e.as_str(),
                r["err"].as_str().unwrap(),
            ),
        }
    }
    c.finish();
}

#[test]
fn oracle_shape() {
    let fx = fixture();
    let mut c = Check::new("shape");
    for (i, r) in fx["shape"].as_array().unwrap().iter().enumerate() {
        let typ = r["type"].as_str().unwrap();
        let b = bx(&r["box"]).unwrap();
        let mut s = shape::new_shape(typ, b);
        let ar = f(&r["ar"]);
        if ar != 0.0 {
            s.set_inner_box_aspect_ratio(ar);
        }
        let (w, h, px, py) = (f(&r["w"]), f(&r["h"]), f(&r["px"]), f(&r["py"]));
        let tag = format!("{i} {typ} {b:?}");
        c.eq_box(
            &format!("{tag} inner"),
            Some(s.get_inner_box()),
            bx(&r["inner"]),
        );
        c.eq_box(
            &format!("{tag} content_box"),
            s.get_inner_box_for_content(w, h),
            bx(&r["content_box"]),
        );
        c.eq_p(
            &format!("{tag} inside"),
            Some(s.get_inside_placement(w, h, px, py)),
            p(&r["inside"]),
        );
        let (dw, dh) = s.get_dimensions_to_fit(w, h, px, py);
        c.eq_p(
            &format!("{tag} fit"),
            Some(Point::new(dw, dh)),
            p(&r["fit"]),
        );
        let (dpx, dpy) = s.get_default_padding();
        c.eq_p(
            &format!("{tag} default_padding"),
            Some(Point::new(dpx, dpy)),
            p(&r["default_padding"]),
        );
        let want_paths: Vec<String> = r["paths"]
            .as_array()
            .map(|a| a.iter().map(|x| x.as_str().unwrap().to_owned()).collect())
            .unwrap_or_default();
        c.eq_s(&format!("{tag} paths"), s.get_svg_path_data(), want_paths);
        c.eq_s(
            &format!("{tag} rect"),
            s.is_rectangular(),
            r["rect"].as_bool().unwrap(),
        );
        c.eq_s(
            &format!("{tag} ar1"),
            s.aspect_ratio1(),
            r["ar1"].as_bool().unwrap(),
        );
        let center = p(&r["center"]).unwrap();
        let corner = p(&r["corner"]).unwrap();
        let v1 = center.vector_to(&corner);
        let trace = shape::trace_to_shape_border(s.as_ref(), corner, corner.add_vector(&v1));
        c.eq_p(&format!("{tag} trace"), Some(trace), p(&r["trace"]));
    }
    for r in fx["limit_ar"].as_array().unwrap() {
        let (lw, lh) = shape::limit_ar(f(&r["w"]), f(&r["h"]), f(&r["ar"]));
        c.eq_p("limit_ar", Some(Point::new(lw, lh)), p(&r["out"]));
    }
    c.finish();
}
